"use client";

import Image from "next/image";
import { useCallback, useEffect, useRef, useState } from "react";

const slides = [
  {
    src: "/fotos/foto1.PNG",
    alt: "Jacuzzi con burbujas junto a una tabla de quesos, copas de cerveza y vista nocturna de la ciudad",
    eyebrow: "Sumérgete, vive el ritual",
    title: "Bienestar inspirado",
    subtitle: "En la cerveza",
  },
  {
    src: "/fotos/foto7.PNG",
    alt: "Toallas TuBeer Spa, copa de cerveza y reloj de arena sobre la banca de un sauna de madera",
    eyebrow: "Calor • Aroma • Calma",
    title: "Un ritual sensorial",
    subtitle: "Para cuerpo y mente",
  },
  {
    src: "/fotos/foto10.PNG",
    alt: "Sala de masajes para dos con camillas y muro de bambú iluminado",
    eyebrow: "Experiencias en pareja",
    title: "Espacios privados",
    subtitle: "Íntimos y exclusivos",
  },
  {
    src: "/fotos/foto4.PNG",
    alt: "Jacuzzi decorado para cumpleaños con letras luminosas HBD y un letrero de felicitación",
    eyebrow: "Celebra a tu manera",
    title: "Momentos especiales",
    subtitle: "Te mereces lo mejor",
  },
  {
    src: "/fotos/foto6.PNG",
    alt: "Manos con espuma sobre el jacuzzi junto a toallas TuBeer y una copa de cerveza",
    eyebrow: "Malta • Lúpulo • Levadura",
    title: "Circuito de hidromasaje",
    subtitle: "Déjate llevar",
  },
];

const INTERVAL_MS = 6000;
const SWIPE_THRESHOLD = 50;

export default function Hero() {
  const [current, setCurrent] = useState(0);
  const [paused, setPaused] = useState(false);
  const [hovering, setHovering] = useState(false);
  const [reducedMotion, setReducedMotion] = useState(false);
  const pointerStartX = useRef<number | null>(null);

  const goTo = useCallback((index: number) => {
    setCurrent((index + slides.length) % slides.length);
  }, []);
  const next = useCallback(() => goTo(current + 1), [current, goTo]);
  const prev = useCallback(() => goTo(current - 1), [current, goTo]);

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReducedMotion(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);

  const autoplay = !paused && !hovering && !reducedMotion;

  useEffect(() => {
    if (!autoplay) return;
    const id = setTimeout(next, INTERVAL_MS);
    return () => clearTimeout(id);
  }, [autoplay, next]);

  const slide = slides[current];

  return (
    <section
      aria-roledescription="carrusel"
      aria-label="Experiencias TuBeer Spa"
      className="theme-forest relative h-[88svh] min-h-140 w-full overflow-hidden select-none"
      onMouseEnter={() => setHovering(true)}
      onMouseLeave={() => setHovering(false)}
      onFocus={() => setHovering(true)}
      onBlur={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget)) setHovering(false);
      }}
      onKeyDown={(e) => {
        if (e.key === "ArrowRight") next();
        if (e.key === "ArrowLeft") prev();
      }}
      onPointerDown={(e) => {
        pointerStartX.current = e.clientX;
      }}
      onPointerUp={(e) => {
        if (pointerStartX.current === null) return;
        const delta = e.clientX - pointerStartX.current;
        pointerStartX.current = null;
        if (delta > SWIPE_THRESHOLD) prev();
        if (delta < -SWIPE_THRESHOLD) next();
      }}
    >
      {slides.map((s, i) => (
        <div
          key={s.src}
          role="group"
          aria-roledescription="diapositiva"
          aria-label={`${i + 1} de ${slides.length}`}
          aria-hidden={i !== current}
          className={`absolute inset-0 transition-opacity duration-1000 ease-out ${
            i === current ? "opacity-100" : "opacity-0"
          }`}
        >
          <Image
            src={s.src}
            alt={s.alt}
            fill
            sizes="100vw"
            preload={i === 0}
            draggable={false}
            className={`object-cover transition-transform duration-7000 ease-out motion-reduce:transition-none ${
              i === current ? "scale-105" : "scale-100"
            }`}
          />
        </div>
      ))}

      {/* Velo para legibilidad del texto */}
      <div className="pointer-events-none absolute inset-0 bg-linear-to-t from-forest-deep/85 via-forest-deep/35 to-forest-deep/20" />

      <div
        key={current}
        aria-live={autoplay ? "off" : "polite"}
        className="relative z-10 mx-auto flex h-full max-w-6xl flex-col items-center justify-center gap-6 px-6 text-center animate-fade-up"
      >
        <h5 className="text-malt">{slide.eyebrow}</h5>
        <span className="divider-malt" />
        <h1>{slide.title}</h1>
        <p className="text-h4 text-display-thin">{slide.subtitle}</p>
      </div>

      <button
        type="button"
        onClick={prev}
        aria-label="Diapositiva anterior"
        className="absolute left-4 top-1/2 z-20 hidden -translate-y-1/2 rounded-full border border-border p-3 text-cream transition-colors hover:border-malt hover:text-malt sm:block"
      >
        <Chevron direction="left" />
      </button>
      <button
        type="button"
        onClick={next}
        aria-label="Diapositiva siguiente"
        className="absolute right-4 top-1/2 z-20 hidden -translate-y-1/2 rounded-full border border-border p-3 text-cream transition-colors hover:border-malt hover:text-malt sm:block"
      >
        <Chevron direction="right" />
      </button>

      <div className="absolute inset-x-0 bottom-8 z-20 flex items-center justify-center gap-4">
        <div className="flex items-center gap-3">
          {slides.map((s, i) => (
            <button
              key={s.src}
              type="button"
              onClick={() => goTo(i)}
              aria-label={`Ir a la diapositiva ${i + 1}`}
              aria-current={i === current}
              className="group py-3"
            >
              <span
                className={`block h-px transition-all duration-500 ${
                  i === current ? "w-10 bg-malt" : "w-5 bg-cream/50 group-hover:bg-cream"
                }`}
              />
            </button>
          ))}
        </div>
        <button
          type="button"
          onClick={() => setPaused((p) => !p)}
          aria-label={paused ? "Reanudar carrusel" : "Pausar carrusel"}
          className="text-cream/70 transition-colors hover:text-malt"
        >
          {paused ? <PlayIcon /> : <PauseIcon />}
        </button>
      </div>
    </section>
  );
}

function Chevron({ direction }: { direction: "left" | "right" }) {
  return (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.25" aria-hidden>
      <path d={direction === "left" ? "M15 5l-7 7 7 7" : "M9 5l7 7-7 7"} />
    </svg>
  );
}

function PauseIcon() {
  return (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor" aria-hidden>
      <rect x="6" y="5" width="4" height="14" />
      <rect x="14" y="5" width="4" height="14" />
    </svg>
  );
}

function PlayIcon() {
  return (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor" aria-hidden>
      <path d="M7 5l12 7-12 7z" />
    </svg>
  );
}
